   670          const unsigned char *szCurrent,
   671          const unsigned char **szCurrentOut,
   672          unsigned int iType,
   673          unsigned int iWidth,
   674          unsigned int iHeight) {
   675      // get the type of the skin
   676      const unsigned int iMasked = (unsigned int)(iType & 0xF);
   677
   678      if (0x6 == iMasked) {
   679          szCurrent += iWidth;
   680      }
   681      if (0x7 == iMasked) {
   682          const size_t iLen = std::strlen((const char *)szCurrent);
   683          szCurrent += iLen + 1;
   684      } else if (iMasked || !iType) {
   685          if (iMasked || !iType || (iType && iWidth && iHeight)) {
   686              // ParseTextureColorData(..., aiTexture::pcData == bad_texel) will simply
   687              // return the size of the color data in bytes in iSkip
   688              unsigned int iSkip = 0;
   689
