   691              tex.pcData = bad_texel;
   692              tex.mHeight = iHeight;
   693              tex.mWidth = iWidth;
   694              ParseTextureColorData(szCurrent, iMasked, &iSkip, &tex);
   695
   696              // FIX: Important, otherwise the destructor will crash
   697              tex.pcData = nullptr;
   698
   699              // skip length of texture data
   700              szCurrent += iSkip;
   701          }
   702      }
